package org.sormus.downloads;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class DownloadsActivity extends Activity {
 private DownloadsApi api;private EditText server,code,phone,link;private TextView message,selection,history;private Button send;private final ArrayList<Uri> files=new ArrayList<>();private final ExecutorService executor=Executors.newSingleThreadExecutor();private boolean pairing=false;private IncomingTransfer pendingReceived;private boolean receivedDispatched;
 private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}private TextView label(LinearLayout l,String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(218,239,235));t.setPadding(0,dp(10),0,dp(6));l.addView(t);return t;}
 private EditText input(LinearLayout l,String title,String value){label(l,title,13);EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setTextSize(16);l.addView(e,new LinearLayout.LayoutParams(-1,dp(52)));return e;}
 private Button button(LinearLayout l,String title,Runnable action){Button b=new Button(this);b.setText(title);l.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);api=new DownloadsApi(this);receivedDispatched=b!=null&&b.getBoolean("receivedDispatched",false);if(receivedDispatched&&TransferInbox.external(getIntent().getAction())){finish();return;}if(IncomingTransfer.paired(this)&&TransferInbox.external(getIntent().getAction())){try{IncomingTransfer incoming=IncomingTransfer.read(getIntent());if(incoming!=null){receivedDispatched=true;Intent route=new Intent(getIntent());route.setClass(this,ReceiveActivity.class);route.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(route);}}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}finish();return;}ScrollView scroll=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(22),dp(22),dp(22),dp(30));l.setBackgroundColor(Color.rgb(13,27,33));scroll.addView(l);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});label(l,"Sormus Downloads",28);label(l,"Send files and torrents to your PC",16);server=input(l,"PC address",api.preferences.getString("server",""));server.setHint("http://192.168.1.10:7041");phone=input(l,"Phone name",api.preferences.getString("name",Build.MODEL));code=input(l,"One-time pairing code","");code.setInputType(2);button(l,"Pair with PC",()->pair());message=label(l,api.preferences.contains("token")?"Paired. Ready to send.":"In the PC administrator: Downloads inbox → Pair a phone.",14);selection=label(l,"No files selected",15);button(l,"Choose files",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,40);});link=input(l,"Magnet or torrent link","");send=button(l,"Send to PC",()->send());button(l,"Refresh transfers",()->refresh());history=label(l,"",14);button(l,"Enable transfer notifications",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},41);else show("Transfer notifications are enabled.");});button(l,"Forget this PC",()->{api.preferences.edit().clear().apply();message.setText("Disconnected on this phone. The PC administrator can revoke its grant.");});accept(getIntent());}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);receivedDispatched=false;accept(i);}
 private void add(Uri u){if(u!=null&&files.size()<20&&"content".equalsIgnoreCase(u.getScheme())&&!files.contains(u))files.add(u);}
 private void accept(Intent i){if(i==null||!TransferInbox.external(i.getAction()))return;try{IncomingTransfer incoming=IncomingTransfer.read(i);if(incoming==null)return;if(IncomingTransfer.paired(this)){receivedDispatched=true;Intent route=new Intent(i);route.setClass(this,ReceiveActivity.class);route.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(route);finish();return;}pendingReceived=incoming;files.clear();files.addAll(incoming.files);link.setText(incoming.link);selection.setText("Pair this phone to automatically send the received selection.");}catch(Exception e){show(e.getMessage());}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=40||result!=RESULT_OK||data==null)return;pendingReceived=null;files.clear();if(data.getClipData()!=null)for(int n=0;n<data.getClipData().getItemCount();n++)add(data.getClipData().getItemAt(n).getUri());else add(data.getData());for(Uri u:files)try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}selection.setText(files.size()+" file(s) selected");}
 private void pair(){if(pairing)return;try{String address=TransferProtocol.server(server.getText().toString()),name=phone.getText().toString().trim(),value=code.getText().toString().trim();if(!value.matches("[0-9]{8}")||name.isEmpty()||name.length()>64)throw new Exception("Enter the phone name and eight-digit pairing code.");String old=api.preferences.getString("server","");if(!old.equals(address))api.preferences.edit().remove("token").apply();api.preferences.edit().putString("server",address).putString("name",name).apply();pairing=true;message.setText("Pairing…");executor.execute(()->{try{JSONObject out=api.json("POST","/api/file-downloads/native/pair",new JSONObject().put("code",value).put("name",name));api.preferences.edit().putString("token",out.getString("token")).apply();runOnUiThread(()->{code.setText("");message.setText("Paired. Files will go to the PC Downloads folder.");if(pendingReceived!=null){try{receivedDispatched=true;pendingReceived.start(this);pendingReceived=null;finish();}catch(Exception e){show(e.getMessage());}}});}catch(Exception e){show(e.getMessage());}finally{pairing=false;}});}catch(Exception e){show(e.getMessage());}}
 private void send(){if(TransferService.running){show("A transfer is already running. Check its notification.");return;}if(!api.preferences.contains("token")){show("Pair this phone first.");return;}String url=link.getText().toString().trim();if(files.isEmpty()&&!TransferProtocol.link(url)){show("Select files or enter a magnet/torrent link.");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},41);startForegroundService(IncomingTransfer.serviceIntent(this,files,url));files.clear();link.setText("");selection.setText("Transfer started. Check the notification and Recent transfers.");}
 private void refresh(){executor.execute(()->{try{JSONObject out=api.json("GET","/api/file-downloads/native/status",null);JSONArray jobs=out.getJSONArray("jobs");StringBuilder text=new StringBuilder();for(int n=0;n<Math.min(20,jobs.length());n++){JSONObject j=jobs.getJSONObject(n);text.append(j.optString("savedName",j.optString("name"))).append("\n").append(j.optString("status")).append("\n");if(j.has("message"))text.append(j.getString("message")).append("\n");text.append("\n");}runOnUiThread(()->history.setText(text.length()==0?"No transfers yet.":text.toString()));}catch(Exception e){show(e.getMessage());}});}
 @Override protected void onSaveInstanceState(Bundle state){state.putBoolean("receivedDispatched",receivedDispatched);super.onSaveInstanceState(state);}
 private void show(String s){runOnUiThread(()->{if(!isFinishing())message.setText(s);});}@Override protected void onDestroy(){executor.shutdown();super.onDestroy();}
}
